/**
 * Release signing, read from `keystore.properties`.
 *
 * The author's other apps ship release APKs signed with the *debug* key, which
 * is fine for a private build and wrong for anything someone else installs: the
 * debug key is a shared secret baked into the Android SDK, so anyone can produce
 * an update that the platform will accept as coming from you.
 *
 * So: a real key, generated once, referenced by path, never committed. When the
 * file is absent the release build still assembles as unsigned, and says so
 * loudly, rather than silently falling back to a debug signature.
 *
 * Looked for at the repository root, next to `keystores/`, and then in the
 * Gradle root. The first location is where tooling/setup-signing.ps1 writes it,
 * because the keystore lives there; checking only one of the two is how a
 * correctly generated key ends up unused with a build that claims there is
 * none.
 */
val keystorePropertiesFile = sequenceOf(
    rootProject.file("../keystore.properties"),
    rootProject.file("keystore.properties"),
).firstOrNull { it.isFile }

val keystoreProperties = Properties().apply {
    keystorePropertiesFile?.inputStream()?.use { load(it) }
}
val hasReleaseKey = keystoreProperties.getProperty("storeFile") != null

// Machine-local settings. android/local.properties is git-ignored; nothing here
// is a secret, but it names this developer's network, which must not be public.
// Without it the build uses inert placeholders and no tailnet hosts.
val localProperties = Properties().apply {
    rootProject.file("local.properties").takeIf { it.exists() }?.inputStream()?.use { load(it) }
}

val gatewayUrl = localProperties.getProperty("gatewayUrl")?.trim()
    ?.takeIf { it.isNotEmpty() } ?: "http://127.0.0.1:8788"

android {
    namespace = "dev.herdrnotify.app"
    compileSdk = 36

    defaultConfig {
        applicationId = "dev.herdrnotify.app"
        minSdk = 26
        targetSdk = 36
        versionCode = 7
        versionName = "0.1.5"

        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        vectorDrawables.useSupportLibrary = true
    }

        signingConfigs {
            if (hasReleaseKey) {
                create("release") {
                    // The path in the file is absolute, written by
                    // setup-signing.ps1. A relative one would resolve against
                    // this module directory, and the resulting "file not found"
                    // does not name the file it looked for.
                    storeFile = File(keystoreProperties.getProperty("storeFile"))
                    storePassword = keystoreProperties.getProperty("storePassword")
                    keyAlias = keystoreProperties.getProperty("keyAlias")
                    keyPassword = keystoreProperties.getProperty("keyPassword")
                    // Enables the v2/v3 scheme so the APK is verifiable on Android 11+
                    // without the legacy JAR signature.
                    enableV1Signing = true
                    enableV2Signing = true
                    enableV3Signing = true
                }
            }
        }


    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
            isMinifyEnabled = false
            // Where this build's gateway is reached by default: the tailnet
            // proxy (tailscale serve, tailnet only). The in-app dialog overrides.
            buildConfigField("String", "DEFAULT_GATEWAY_URL", "\"$gatewayUrl\"")
        }
        release {
            buildConfigField("String", "DEFAULT_GATEWAY_URL", "\"$gatewayUrl\"")
            // Shrinking and obfuscation on for anything that leaves this machine.
            // The author's other apps ship with it off, which leaves the full
            // class and resource table readable in the APK.
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
            signingConfig = if (hasReleaseKey) {
                signingConfigs.getByName("release")
            } else {
                logger.warn(
                    "No keystore.properties found: the release APK will be UNSIGNED. " +
                        "See docs/android-release.md before distributing it.",
                )
                null
            }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
        // minSdk is 26 so desugaring is not needed for java.time, which the
        // notification timestamp formatting uses.
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    packaging {
        resources {
            excludes += setOf(
                "/META-INF/{AL2.0,LGPL2.1}",
                "/META-INF/DEPENDENCIES",
                "META-INF/*.kotlin_module",
            )
        }
    }

    testOptions {
        unitTests.isReturnDefaultValues = true
    }
}

/**
 * Replaces the old `android.kotlinOptions { }` block, which built-in Kotlin does
 * not support.
 *
 * `jvmTarget` is deliberately absent: it now defaults to
 * `compileOptions.targetCompatibility`, which is set to 17 above. Declaring it
 * in both places is how they drift apart — one gets bumped, the other does not,
 * and the mismatch surfaces as a confusing toolchain error much later.
 */
kotlin {
    compilerOptions {
        freeCompilerArgs.addAll(
            "-opt-in=kotlin.RequiresOptIn",
            "-opt-in=kotlinx.coroutines.ExperimentalCoroutinesApi",
        )
    }
}

